const data = $input.first().json;

const unplaced = Array.isArray(data.unplaced)
  ? data.unplaced
  : [];

const conflicts = unplaced.map(item => {
  const detail =
    item.detail ||
    item.reason ||
    "No additional details available";

  const detailLower = detail.toLowerCase();

  let reasonCode = item.reason_code || "UNKNOWN";

  // Normalize scheduler reason codes for downstream analysis.
  if (detailLower.includes("no legal timeslot")) {
    reasonCode = "NO_LEGAL_TIMESLOT";
  } else if (
    detailLower.includes("rooms exist") &&
    detailLower.includes("occupied")
  ) {
    reasonCode = "ROOM_OCCUPIED";
  } else if (
    detailLower.includes("capacity")
  ) {
    reasonCode = "ROOM_CAPACITY";
  }

  return {
    course_id: item.course_id,
    course: item.code || item.course || null,
    title: item.title || null,
    reason_code: reasonCode,
    detail
  };
});

return [
  {
    json: {
      status: "CONFLICT",
      success: false,
      violations_count: conflicts.length,
      conflicts,
      message: `${conflicts.length} course(s) could not be scheduled.`,
      ai_ready: true
    }
  }
];

