];

const data = $input.first().json;

const placed = Array.isArray(data.placed) ? data.placed : [];

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

const rows = placed.map((item) => {
  const course =
    item.course ??
    item.course_code ??
    item.code ??
    item.name ??
    "";

  const title = item.title ?? "";

  const lecturer =
    item.lecturer ??
    item.instructor ??
    item.professor ??
    "";

  const room =
    item.room ??
    item.room_code ??
    "";

  const day =
    item.day ??
    item.day_of_week ??
    "";

  const time =
    item.time ??
    item.timeslot ??
    item.time_slot ??
    "";

  return `
    <tr>
      <td>${escapeHtml(course)}</td>
      <td>${escapeHtml(title)}</td>
      <td>${escapeHtml(lecturer)}</td>
      <td>${escapeHtml(room)}</td>
      <td>${escapeHtml(day)}</td>
      <td>${escapeHtml(time)}</td>
    </tr>
  `;
}).join("");

const html = `
