<body>

  <div class="container">

    <h1>University Timetable</h1>

    <div class="subtitle">
      Automatically generated by the Auto-Scheduler
    </div>

    <div class="summary">

      <div class="summary-card">
        Scheduled Courses
        <strong>${placed.length}</strong>
