      <div class="summary-card">
        Unplaced Courses
        <strong>${
          Array.isArray(data.unplaced)
            ? data.unplaced.length
            : 0
        }</strong>
      </div>

      <div class="summary-card">
        Verification Errors
        <strong>${data.violations_count ?? 0}</strong>
      </div>

    </div>

    <div class="table-wrapper">

      <table>

        <thead>
          <tr>
            <th>Course</th>
            <th>Title</th>
            <th>Lecturer</th>
            <th>Room</th>
            <th>Day</th>
            <th>Time</th>
          </tr>
        </thead>

        <tbody>

          ${
            rows ||
            `
            <tr>
              <td colspan="6" class="empty">
                No scheduled courses found.
              </td>
            </tr>
            `
          }

        </tbody>

      </table>

    </div>

    <div class="footer">
      Generated by the Auto-Scheduler n8n workflow.
    </div>

