`;

return [
  {
    json: {
      ...data,
      status: "SUCCESS",
      success: true,
      placed_count: placed.length,
      unplaced_count: Array.isArray(data.unplaced)
        ? data.unplaced.length
        : 0,
      message: "Timetable generated successfully.",
      html
    }
  }
];

const data = $json;

const errors = [];

if (!Array.isArray(data.placed)) {
  errors.push("placed must be an array");
}

if (!Array.isArray(data.unplaced)) {
  errors.push("unplaced must be an array");
}

if (typeof data.violations_count !== "number") {
  errors.push("violations_count must be a number");
}

return [
  {
    json: {
      ...data,
      contract_valid: errors.length === 0,
      contract_errors: errors
    }
  }
];
